    constructor(C _c) { c = _c; }

    // We take parameters to drive setSlopes and then call rate; we observe whether setSlopes reverts
    // and whether rate call (which is non-view) either reverts or returns a uint. We assert the general
    // property: setSlopes must revert iff kink==0 || kink>=1e27, and if setSlopes succeeds then a subsequent
    // call to rate on any vault/address that has code (we cannot create vaults here) will not fail solely
    // due to AddressEmptyCode — we approximate by asserting that when setSlopes succeeds, calling rate
    // does not revert with AddressEmptyCode when targeting an address with non-zero code length. Since
    // we cannot deploy a vault here, we instead assert the logical relation about setSlopes revert condition
    // which is intrinsic to C's behavior and observable: it must revert exactly when kink==0 || kink>=1e27.

    function run(address asset, uint256 kink, uint256 slope0, uint256 slope1) public payable {
        // prepare SlopeData bytes to call setSlopes via the ABI
        // Build calldata: setSlopes(address, (uint256,uint256,uint256))
        bytes4 sig = c.setSlopes.selector;
        // pack SlopeData as (kink,slope0,slope1)
        bytes memory slopesEncoded = abi.encode(kink, slope0, slope1);

