        // Call setSlopes and catch revert
        try c.setSlopes(asset, IVaultAdapter.SlopeData({kink: kink, slope0: slope0, slope1: slope1})) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // The general rule: setSlopes reverts iff kink == 0 || kink >= 1e27
