contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    // We rely only on public/external surface of C. We cannot read slopeData directly
    // so we use behavior: calling rate(...) after setting slopes should not revert
    // and should produce a numeric interest rate; additionally if setSlopes reverts
    // due to invalid kink, a subsequent rate call with same inputs should behave as if slopes not updated.

    // params:
    // _asset: asset address to set slopes for
    // kink: candidate kink value (must be in uint256 range)
    // slope0, slope1: candidate slopes
    // vault, assetForRate: addresses used to call rate() to observe behavior
    // elapsedInfluence: a small uint used to try to trigger the utilization branch via vault's reported indexes; it's just a parameter to be passed to rate's callers (we cannot control vault impl)
    function run(address _asset, uint256 kink, uint256 slope0, uint256 slope1, address vault, address assetForRate) public payable {
        require(_asset != address(0) && vault != address(0) && assetForRate != address(0));

        // read a before-value: call rate to observe current behavior (may revert depending on vault mock), capture whether it reverts
        bool beforeReverted;
        uint256 beforeRate = 0;
        try c.rate(vault, assetForRate) returns (uint256 r) {
            beforeReverted = false;
            beforeRate = r;
        } catch {
            beforeReverted = true;
        }

        // Now attempt to set slopes on _asset
        bool setReverted;
        C.SlopeData memory sd = C.SlopeData({kink: kink, slope0: slope0, slope1: slope1});
        try c.setSlopes(_asset, sd) {
            setReverted = false;
        } catch {
            setReverted = true;
        }

        // After the attempt, call rate again to observe effect
        bool afterReverted;
        uint256 afterRate = 0;
        try c.rate(vault, assetForRate) returns (uint256 r2) {
            afterReverted = false;
            afterRate = r2;
        } catch {
            afterReverted = true;
        }

        // General rule asserted:
        // If setSlopes reverted due to invalid kink (i.e., kink == 0 or kink >= 1e27), then the observable behavior of rate for the same (vault, asset) pair must be unchanged: both revert flags equal and returned rates equal when not reverted.
        // If setSlopes succeeded, at minimum the contract must still allow calling rate (it may still revert if vault causes revert) — but we can assert a weaker but general property:
        //   - If setSlopes reverted then (beforeReverted == afterReverted) && (if not reverted then beforeRate == afterRate)
        //   - If setSlopes succeeded then it's not allowed that the call suddenly flips from non-reverting to reverting solely due to setting slopes for a different asset (we assert: if before did not revert and set succeeded then after must not revert). This captures that successful set on some asset should not break rate observation on an unrelated (vault, asset) pair when it previously worked.

        assert(
            (setReverted && beforeReverted == afterReverted && (beforeReverted || beforeRate == afterRate))
            || (!setReverted && (!beforeReverted ==> !afterReverted))
        );
    }

    // Solidity doesn't have direct ==> operator; implement as a pure boolean expression via a helper inlined in the assert context.
    receive() external payable {}
}

